<?php
 namespace QQWorld\Setup\Model\Description\Mixin; class MixinFactory { const SPAN_MIXIN = 'span'; const BOLD_MIXIN = 'b'; const BRAKE_MIXIN = 'br'; const PARAGRAPH_MIXIN = 'p'; const HEADER_MIXIN = 'h1'; const ITALIC_MIXIN = 'i'; private $typeClassMap = [ self::SPAN_MIXIN => SpanMixin::class, self::BOLD_MIXIN => BoldMixin::class, self::BRAKE_MIXIN => BrakeMixin::class, self::PARAGRAPH_MIXIN => ParagraphMixin::class, self::HEADER_MIXIN => HeaderMixin::class, self::ITALIC_MIXIN => ItalicMixin::class, ]; private $objectManager; public function __construct(\QQWorld\Framework\ObjectManagerInterface $objectManager) { $this->objectManager = $objectManager; } public function create($mixinType) { if (!isset($this->typeClassMap[$mixinType])) { throw new \InvalidArgumentException(sprintf('Undefined mixin type: %s.', $mixinType)); } $mixin = $this->objectManager->get($this->typeClassMap[$mixinType]); if (!$mixin instanceof \QQWorld\Setup\Model\Description\Mixin\DescriptionMixinInterface) { throw new \InvalidArgumentException( sprintf( 'Class "%s" must implement \QQWorld\Setup\Model\Description\Mixin\DescriptionMixinInterface.', get_class($mixin) ) ); } return $mixin; } } 